import{_ as l,l as r,o as e,c as s,v as n,p as i,x as o,d,i as h,S as g}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"下界 Ω(n log n)","description":"","frontmatter":{"title":"下界 Ω(n log n)","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sort-lower-bound.md","filePath":"cs/sort-lower-bound.md","lastUpdated":1789023840000}'),p={name:"cs/sort-lower-bound.md"};function _(c,a,m,u,E,A){const t=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=n('<h1 id="下界-ω-n-log-n" tabindex="-1">下界 Ω(n log n) <a class="header-anchor" href="#下界-ω-n-log-n" aria-label="Permalink to &quot;下界 Ω(n log n)&quot;">​</a></h1><div class="epigraph"><p>任何以比较为唯一信息的排序，在最坏情形下至少要问够区分 $n!$ 种排列的那些位。</p><footer>—— 据 Ford and Johnson, A Tournament Problem, 1959；Knuth, TAOCP vol. 3；CLRS 第 8 章整理</footer></div><p>上一课<a href="/cs/quicksort-3way">三路快排</a>与更早的归并、堆排都停在 \\(O(n\\log n)\\) 比较。本课不重写分区。缺口是：这是巧合还是模型里的墙。没有下界，后课线性时间排序会看起来像「推翻了快排」。本课只钉<strong>比较决策树</strong>最坏高度 \\(\\Omega(n\\log n)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>比较排序每次问 \\(a_i\\le a_j\\) 或否，把输入排列集切成两块。要产出正确排列，树的叶必须至少覆盖 \\(n!\\) 种可能（假定键互异）。二叉树高度至少 \\(\\log_2(n!)\\)。Stirling：\\(n!=\\omega\\bigl((n/e)^n\\bigr)\\)，故 \\(\\log(n!)=\\Omega(n\\log n)\\)。</p><p>缺口因此不是再给一个 \\(O\\) 算法，而是比较模型的信息量。渐近记号课已能写 \\(\\Omega\\)；这里第一次把它用在<strong>任意</strong>该类算法上，而不只是某份伪代码。</p><h3 id="下界不是「排序很慢」" tabindex="-1">下界不是「排序很慢」 <a class="header-anchor" href="#下界不是「排序很慢」" aria-label="Permalink to &quot;下界不是「排序很慢」&quot;">​</a></h3><p>它只约束<strong>以两两比较为信息源</strong>的过程。读键的数字、当桶下标、当基数的一位，都不在本模型里。那些是下一课的出口，不是对本课的反驳。</p><p><span class="marginnote">决策树每个内节点一次比较，叶是一个排列。最坏比较次数是树高。平均高度同样 \\(\\Omega(n\\log n)\\)，因为叶在第 \\(h\\) 层最多 \\(2^h\\) 个。信息论说法与计数说法是同一棵树。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定 \\(n\\)，键互异。任何比较排序对应一棵三路或两路树；本课用两路 \\(\\le\\)。正确性要求每种排列走到某叶，且该叶输出该排列。因此 \\(h\\ge\\log_2(n!)=\\Omega(n\\log n)\\)。归并的 \\(\\Theta(n\\log n)\\) 因此是比较模型最坏意义下渐近紧的（常数因子另算）。</p>',11)),(e(),i(g,null,{default:o(()=>[h(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PERM%5B%22n!%20%E7%A7%8D%E6%8E%92%E5%88%97%22%5D%20--%3E%20ASK%5B%22%E6%AF%94%E8%BE%83%20a_i%20%E4%B8%8E%20a_j%22%5D%0A%20%20ASK%20--%3E%20L%5B%22%E8%B5%B0%E5%B7%A6%22%5D%0A%20%20ASK%20--%3E%20R%5B%22%E8%B5%B0%E5%8F%B3%22%5D%0A%20%20L%20--%3E%20LEAF%5B%22%E5%8F%B6%EF%BC%9A%E4%B8%80%E4%B8%AA%E6%8E%92%E5%88%97%22%5D%0A%20%20R%20--%3E%20LEAF%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>相等键使排列变少，下界只更弱；算法仍常按互异分析。本课不把稳定排序的额外信息写进树。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了这堵墙，归并与堆排的最坏 \\(\\Theta(n\\log n)\\) 不再是「还没优化好」。快排期望同阶，最坏越过墙之上（平方），墙管的是最坏下界，不管期望上界。后课若声称 \\(O(n)\\)，必须先声明离开比较模型。</p><p>对手论证：对手始终回答以保持尽可能多的一致排列，逼树走深。与决策树计数等价，本课不并行展开两套。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出最优比较常数（Ford–Johnson 的精确最少比较是另一条线）。不处理部分信息（已知部分有序）。也不把 \\(\\Omega(n\\log n)\\) 套到查找、选择：选择第 \\(k\\) 小的比较下界是 \\(\\Omega(n)\\)，不是 \\(n\\log n\\)。</p><p>后课默认：比较排序最坏 \\(\\Omega(n\\log n)\\)。线性时间排序必须动用值域或位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>比较决策树叶数 \\(\\ge n!\\)，高度 \\(\\Omega(n\\log n)\\)。</li><li>墙只约束比较模型；不否定计数与基数。</li><li>归并/堆排最坏上界与此匹配。</li><li>出处：Knuth, TAOCP vol. 3；CLRS 第 8.1 节。</li></ul>',9))])}const B=l(p,[["render",_]]);export{f as __pageData,B as default};
